//will open DeepL in the browser

// based on work by Aatmaj-Zephyr
// see https://github.com/windingwind/zotero-actions-tags/discussions/535

// Use with Zotero Actions and Tags Plugin
// Settings:
// - Name: Whatever you like
// - Event: "Program Startup" (-> restart Zotero after saving!)
// - Operation: "Script"
// - Data: Copy&Paste this entire script
// - Shortcut: Whatever you like
// - Menu Label: No need, Button will come up with right click on selected text


const PLUGIN_ID = "deepl-no-api@yourdomain.com";

// A global (module-level) variable to hold the last text selection

// 1. Listen to text-selection popups
let lastSelectedText = "";
let selectionTimeout = null;

// 1. Listen to text-selection popups
Zotero.Reader.registerEventListener("renderTextSelectionPopup", (event) => {
  const { params } = event;
  const sel = params.text || (params.annotation && params.annotation.text);

  if (typeof sel === "string" && sel.trim().length > 0) {
    lastSelectedText = sel.trim();

    // Clear previous timeout if it exists
    if (selectionTimeout) {
      clearTimeout(selectionTimeout);
    }

    // Auto-expire after few seconds
    selectionTimeout = setTimeout(() => {
      lastSelectedText = "";
      selectionTimeout = null;
    }, 5000);
  }
}, PLUGIN_ID);

// 2. Listen to the context menu event
Zotero.Reader.registerEventListener("createViewContextMenu", (event) => {
  const { append } = event;

  if (lastSelectedText && lastSelectedText.length > 0) {

    // --- Start DeepL ---
    append({
      label: `🔍 DeepL`,
      onCommand: () => {
        const query = encodeURIComponent(lastSelectedText);
        Zotero.launchURL(`www.deepl.com/de/translator#en/de/${query}`);
      },
    });


  }
}, PLUGIN_ID);
